import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    rows = {}
    cols = {}
    ans = 0

    for _ in range(M):
        r = int(next(it))
        c = int(next(it))

        # Remove all pieces in row r
        s = rows.pop(r, None)
        if s:
            while s:
                col = s.pop()
                cs = cols.get(col)
                if cs is not None:
                    cs.remove(r)
                    if not cs:
                        del cols[col]
                ans -= 1

        # Remove all pieces in column c
        s = cols.pop(c, None)
        if s:
            while s:
                row = s.pop()
                rs = rows.get(row)
                if rs is not None:
                    rs.remove(c)
                    if not rs:
                        del rows[row]
                ans -= 1

        # Place a piece at (r, c)
        rows.setdefault(r, set()).add(c)
        cols.setdefault(c, set()).add(r)
        ans += 1

    print(ans)

if __name__ == "__main__":
