def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    N = data[0]
    P = tuple(data[1:1 + N])
    Q = tuple(data[1 + N:1 + 2 * N])

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i

    def rank(perm):
        remaining = list(range(1, N + 1))
        res = 0
        for i, x in enumerate(perm):
            j = remaining.index(x)
            res += j * fact[N - i - 1]
            remaining.pop(j)
        return res

    if P < Q:
        ans = rank(Q) - rank(P) - 1
    else:
        ans = 0

    print(ans)

if __name__ == "__main__":
