def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    base = N + 1

    edges = set()
    deg = [0] * (N + 1)
    first_a = first_b = -1
    distinct = 0

    idx = 2
    for _ in range(M):
        A = data[idx]
        B = data[idx + 1]
        idx += 2

        if first_a == -1:
            first_a, first_b = A, B

        if A > B:
            A, B = B, A

        key = A * base + B
        if key not in edges:
            edges.add(key)
            distinct += 1
            deg[A] += 1
            deg[B] += 1

    def has_edge(u, v):
        if u > v:
            u, v = v, u
        return u * base + v in edges

    def ok(x, y):
        if x == y:
            return False

        rem = distinct - deg[x]
        if rem == 0:
            return True

        cnt = deg[y] - (1 if has_edge(x, y) else 0)
        return cnt == rem

    seen = set()
    a, b = first_a, first_b

    for y in range(1, N + 1):
        if y == a:
            continue
        if ok(a, y):
            u, v = (a, y) if a < y else (y, a)
            seen.add(u * base + v)

    for x in range(1, N + 1):
        if x == b:
            continue
        if ok(b, x):
            u, v = (b, x) if b < x else (x, b)
            seen.add(u * base + v)

    print(len(seen))

